import React, { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";

import { useAppContext } from "../context/AppContext";
import api from "../services/api";
import { formatErrorMessage } from "../utils/errorMessages";

const getRoleFromToken = (token) => {
  try {
    const base64Value = token.split(".")[1];
    const normalized = base64Value.replace(/-/g, "+").replace(/_/g, "/");
    const padded = normalized.padEnd(normalized.length + ((4 - (normalized.length % 4)) % 4), "=");
    const payload = JSON.parse(atob(padded));
    return payload.role;
  } catch (error) {
    return null;
  }
};

const Login = () => {
  const navigate = useNavigate();
  const { preloadAfterLogin, prefetching } = useAppContext();
  const [formData, setFormData] = useState({ username: "", password: "" });
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) {
      const role = getRoleFromToken(token);
      if (role === "admin") {
        navigate("/admin", { replace: true });
      } else if (role === "client") {
        navigate("/client", { replace: true });
      }
    }
  }, [navigate]);

  const handleChange = (event) => {
    const { name, value } = event.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setError("");
    setLoading(true);

    try {
      const response = await api.post("/auth/login", formData);
      const token = response.data.access_token;
      const role = getRoleFromToken(token);
      const userData = response.data.user || { username: formData.username, role };

      localStorage.setItem("token", token);
      localStorage.setItem("user", JSON.stringify(userData));
      await preloadAfterLogin(role);

      if (role === "admin") {
        navigate("/admin");
      } else {
        navigate("/client");
      }
    } catch (err) {
      setError(formatErrorMessage(err.response?.data?.detail, "Something went wrong"));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-shell">
      <div className="auth-hero">
        <p className="eyebrow">College Resource Booking</p>
        <h1>Streamlined reservations for every block and department.</h1>
        <p>
          Reserve halls, labs, and rooms from one clean dashboard designed for
          students and block administrators.
        </p>
      </div>

      <div className="auth-card">
        <h2>Sign In</h2>
        <p>Use your account credentials to continue.</p>

        <form onSubmit={handleSubmit} className="auth-form">
          <label>
            <span>Username</span>
            <input
              type="text"
              name="username"
              value={formData.username}
              onChange={handleChange}
              required
            />
          </label>

          <label>
            <span>Password</span>
            <input
              type="password"
              name="password"
              value={formData.password}
              onChange={handleChange}
              required
            />
          </label>

          {error ? <div className="alert error">{String(error)}</div> : null}

          <button type="submit" className="primary-button auth-button" disabled={loading || prefetching}>
            {loading || prefetching ? <span className="button-spinner" /> : "Login"}
          </button>
        </form>

        <p className="auth-link">
          New user? <Link to="/register">Create an account</Link>
        </p>
      </div>
    </div>
  );
};

export default Login;
